/** Newest period first; within one period, the most recently issued first. */
export async function listInvoices(
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  const rows = getDb()
    .select()
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .orderBy(
      desc(invoices.periodStart),
      desc(invoices.createdAt),
      desc(invoices.number),
    )
    .all();
  return rows.map(toInvoice);
}

export async function insertInvoice(
  orgId: OrgId,
  invoice: Omit<Invoice, "id" | "createdAt" | "updatedAt">,
): Promise<Invoice> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(invoices)
    .values({
      id: newId(),
      orgId,
      number: invoice.number,
      amountCents: invoice.amountCents,
      currency: invoice.currency,
      periodStart: invoice.periodStart,
      periodEnd: invoice.periodEnd,
      paidAt: invoice.paidAt,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvoice(row);
}

/**
 * Issues the org's next invoice: allocates a number unique within the org and
 * writes the row in one transaction, so two writers never share a number.
 */
export async function insertNextInvoice(
  orgId: OrgId,
  invoice: Pick<Invoice, "amountCents" | "currency" | "periodStart" | "periodEnd">,
  issuedAt: IsoTimestamp,
): Promise<Invoice> {
  const row = getDb().transaction((tx) => {
    const issued = tx
      .select({ value: count() })
      .from(invoices)
      .where(orgPredicate(invoices.orgId, orgId))
      .get();

    let sequence = (issued?.value ?? 0) + 1;
    while (
      tx
        .select({ id: invoices.id })
        .from(invoices)
        .where(
          and(
            orgPredicate(invoices.orgId, orgId),
            eq(invoices.number, invoiceNumber(sequence)),
          ),
        )
        .get()
    ) {
      sequence += 1;
    }

    return tx
      .insert(invoices)
      .values({
        id: newId(),
        orgId,
        number: invoiceNumber(sequence),
        amountCents: invoice.amountCents,
        currency: invoice.currency,
        periodStart: invoice.periodStart,
        periodEnd: invoice.periodEnd,
        paidAt: null,
        createdAt: issuedAt,
        updatedAt: issuedAt,
      })
      .returning()
      .get();
  });

  return toInvoice(row);
}

export async function findInvoice(
  orgId: OrgId,
  invoiceId: string,
): Promise<Invoice | null> {
  const row = getDb()
    .select()
    .from(invoices)
    .where(and(orgPredicate(invoices.orgId, orgId), eq(invoices.id, invoiceId)))
    .get();
  return row ? toInvoice(row) : null;
}

/** `INV-000001`, `INV-000002`, … — zero-padded so the numbers sort as issued. */
function invoiceNumber(sequence: number): string {
  return `INV-${String(sequence).padStart(6, "0")}`;
