 * Sweeps every live organization's subscription — there is no batch cap, a
 * period that ended has to be billed whatever the fleet size. Archived
 * organizations are skipped entirely. The period and invoice rules live in
 * `renewSubscription`; this job only walks the fleet and counts.
 *
 * Replay-safe: a second run at the same `now` finds every period end after
 * `now` and every due cancellation already ended, so it changes nothing.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    let afterId: string | null = null;

    for (;;) {
      const page = await subscriptionRepo.listSubscriptionsOfLiveOrgs(
        afterId,
        PAGE_SIZE,
      );

      for (const subscription of page) {
        try {
          if (await renewSubscription(subscription, now)) {
            result.processed += 1;
          }
        } catch (error) {
          result.failed += 1;
          logger.error("subscription renewal failed", {
            orgId: subscription.orgId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      if (page.length < PAGE_SIZE) return;
      afterId = page[page.length - 1]?.id ?? null;
    }
  });
}
