/**
 * Period-by-period renewal, invoicing and mid-period proration.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, organizations, subscriptions } from "@/server/db";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { BillingInterval, PlanId, SubscriptionStatus } from "@/types/billing";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function setSubscription(
  tenant: Tenant,
  patch: Partial<{
    plan: PlanId;
    interval: BillingInterval;
    status: SubscriptionStatus;
    seats: number;
    currentPeriodStart: string;
    currentPeriodEnd: string;
    cancelAt: string | null;
  }>,
): Promise<void> {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, tenant.org.id))
    .run();
}

async function invoicesOf(tenant: Tenant) {
  return billingService.listInvoices(tenant.actors.owner, tenant.org.id);
}

async function ownerInvoiceNotifications(tenant: Tenant) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: tenant.userIds.owner,
    unreadOnly: false,
    kind: ["invoice_issued"],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

async function invoiceAuditRows(tenant: Tenant) {
  const page = await listActivity(tenant.actors.owner, {
    orgId: tenant.org.id,
    action: ["billing.invoice_issued"],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  while (detachers.length > 1) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("billing periods", () => {
  it("ends a monthly period on the same day next month, clamped to the month's end", () => {
    const jan31 = new Date("2026-01-31T09:30:00.000Z");
    const feb28 = billingService.nextPeriodEnd(jan31, "monthly");
    expect(feb28.toISOString()).toBe("2026-02-28T09:30:00.000Z");
    expect(billingService.nextPeriodEnd(feb28, "monthly").toISOString()).toBe(
      "2026-03-28T09:30:00.000Z",
    );
    expect(
      billingService.nextPeriodEnd(new Date("2026-12-15T00:00:00.000Z"), "monthly").toISOString(),
    ).toBe("2027-01-15T00:00:00.000Z");
  });

  it("ends an annual period on the same day and month next year", () => {
    expect(
      billingService.nextPeriodEnd(new Date("2028-02-29T12:00:00.000Z"), "annual").toISOString(),
    ).toBe("2029-02-28T12:00:00.000Z");
  });

  it("prorates by whole or started days left, rounded down to cents", () => {
    const period = {
      currentPeriodStart: "2026-04-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    } as const;
    const now = new Date("2026-04-16T02:00:00.000Z"); // 14 days 22 hours left

    expect(billingService.prorateCents(1_000, period as never, now)).toBe(500);
    expect(billingService.prorateCents(1_001, period as never, now)).toBe(500);
    expect(
      billingService.prorateCents(1_000, period as never, new Date("2026-05-01T00:00:00.000Z")),
    ).toBe(0);
  });
});

describe("runBillingRenewalJob", () => {
  it("renews one period per elapsed interval, invoicing each, and is replay-safe", async () => {
    const tenant = await createTenant("renew-behind", "growth");
    await setSubscription(tenant, {
      status: "active",
      seats: 3,
      currentPeriodStart: "2026-01-31T10:00:00.000Z",
      currentPeriodEnd: "2026-02-28T10:00:00.000Z",
    });
    const issued = capture("billing.invoice_issued");
    const now = new Date("2026-05-01T00:00:00.000Z");

    const first = await runBillingRenewalJob(now);

    expect(first.kind).toBe("billing-renewal");
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe("2026-04-28T10:00:00.000Z");
    expect(subscription?.currentPeriodEnd).toBe("2026-05-28T10:00:00.000Z");

    const invoices = await invoicesOf(tenant);
    expect(invoices.map((invoice) => [invoice.periodStart, invoice.periodEnd])).toEqual([
      ["2026-04-28T10:00:00.000Z", "2026-05-28T10:00:00.000Z"],
      ["2026-03-28T10:00:00.000Z", "2026-04-28T10:00:00.000Z"],
      ["2026-02-28T10:00:00.000Z", "2026-03-28T10:00:00.000Z"],
    ]);
    for (const invoice of invoices) {
      expect(invoice.amountCents).toBe(1_900 * 3);
      expect(invoice.currency).toBe("usd");
      expect(invoice.paidAt).toBeNull();
    }
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(issued).toHaveLength(3);
    expect(issued[0]).toMatchObject({ orgId: tenant.org.id, actorId: null, amountCents: 5_700 });
    expect(await invoiceAuditRows(tenant)).toHaveLength(3);
    expect(await ownerInvoiceNotifications(tenant)).toHaveLength(3);

    await runBillingRenewalJob(now);

    expect(await invoicesOf(tenant)).toHaveLength(3);
    expect(issued).toHaveLength(3);
    expect(await invoiceAuditRows(tenant)).toHaveLength(3);
    expect(await ownerInvoiceNotifications(tenant)).toHaveLength(3);
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.currentPeriodEnd).toBe(
      "2026-05-28T10:00:00.000Z",
    );
  });

  it("charges twelve months for an annual period", async () => {
    const tenant = await createTenant("renew-annual", "starter");
    await setSubscription(tenant, {
      status: "active",
      interval: "annual",
      seats: 2,
      currentPeriodStart: "2025-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

    const invoices = await invoicesOf(tenant);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 900 * 2 * 12,
      periodStart: "2026-03-01T00:00:00.000Z",
      periodEnd: "2027-03-01T00:00:00.000Z",
    });
  });

  it("moves the free plan's periods on without invoicing", async () => {
    const tenant = await createTenant("renew-free", "free");
    await setSubscription(tenant, {
      currentPeriodStart: "2026-01-10T00:00:00.000Z",
      currentPeriodEnd: "2026-02-10T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));

    expect(await invoicesOf(tenant)).toHaveLength(0);
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.currentPeriodEnd).toBe(
      "2026-04-10T00:00:00.000Z",
    );
  });

  it("ends a cancellation on its date, moving the org to the free plan once", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    await setSubscription(tenant, {
      status: "canceled",
      currentPeriodStart: "2026-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-04-01T00:00:00.000Z",
      cancelAt: "2026-04-01T00:00:00.000Z",
    });
    const changes = capture("billing.plan_changed");

    await runBillingRenewalJob(new Date("2026-03-31T23:00:00.000Z"));
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("canceled");
    expect(changes).toHaveLength(0);

    const now = new Date("2026-04-02T00:00:00.000Z");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "free",
      status: "active",
      cancelAt: null,
      interval: "monthly",
      currentPeriodStart: "2026-04-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    });
    expect(changes).toEqual([
      expect.objectContaining({ orgId: tenant.org.id, actorId: null, from: "growth", to: "free" }),
    ]);
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("leaves trials, past-due subscriptions and archived orgs alone", async () => {
    const trial = await createTenant("renew-trial", "growth");
    const pastDue = await createTenant("renew-past-due", "growth");
    const archived = await createTenant("renew-archived", "growth");
    const ended = {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    };
    await setSubscription(trial, ended);
    await setSubscription(pastDue, { ...ended, status: "past_due" });
    await setSubscription(archived, { ...ended, status: "active" });
    getDb()
      .update(organizations)
      .set({ archivedAt: "2026-02-15T00:00:00.000Z" })
      .where(eq(organizations.id, archived.org.id))
      .run();

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));

    for (const tenant of [trial, pastDue, archived]) {
      expect((await subscriptionRepo.findSubscription(tenant.org.id))?.currentPeriodEnd).toBe(
        "2026-02-01T00:00:00.000Z",
      );
      expect(await invoicesOf(tenant)).toHaveLength(0);
    }
  });
});

describe("mid-period changes", () => {
  const PERIOD = {
    status: "active" as const,
    currentPeriodStart: "2026-04-01T00:00:00.000Z",
    currentPeriodEnd: "2026-05-01T00:00:00.000Z",
  };
  const MID_PERIOD = new Date("2026-04-16T02:00:00.000Z"); // 15 of 30 days left

  it("charges added seats for the rest of the period and tells only the owner", async () => {
    const tenant = await createTenant("prorate-seats", "growth");
    await setSubscription(tenant, { ...PERIOD, seats: 4 });
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(MID_PERIOD);

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 6 });

    const invoices = await invoicesOf(tenant);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: Math.floor((1_900 * 2 * 15) / 30),
      periodStart: PERIOD.currentPeriodStart,
      periodEnd: PERIOD.currentPeriodEnd,
    });
    expect(await ownerInvoiceNotifications(tenant)).toHaveLength(1);
    expect(await invoiceAuditRows(tenant)).toHaveLength(1);

    const admin = await listNotifications(tenant.actors.admin, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      kind: ["invoice_issued"],
      limit: 50,
      cursor: null,
    });
    expect(admin.items).toHaveLength(0);

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 3 });
    expect(await invoicesOf(tenant)).toHaveLength(1);
  });

  it("charges nothing for seats during a trial", async () => {
    const tenant = await createTenant("prorate-trial-seats", "growth");

    await billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 5 });

    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("charges an upgrade the price difference for the rest of the period", async () => {
    const tenant = await createTenant("prorate-upgrade", "starter");
    await setSubscription(tenant, { ...PERIOD, seats: 2 });
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(MID_PERIOD);

    const subscription = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(subscription.currentPeriodEnd).toBe(PERIOD.currentPeriodEnd);
    expect((await invoicesOf(tenant))[0]?.amountCents).toBe(
      Math.floor(((1_900 - 900) * 2 * 15) / 30),
    );

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });
    expect(await invoicesOf(tenant)).toHaveLength(1);
  });

  it("starts a fresh, fully invoiced period when leaving the free plan", async () => {
    const tenant = await createTenant("prorate-from-free", "free");
    await setSubscription(tenant, { seats: 2 });
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(MID_PERIOD);

    const subscription = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "annual",
    });

    expect(subscription).toMatchObject({
      plan: "starter",
      status: "active",
      interval: "annual",
      currentPeriodStart: "2026-04-16T02:00:00.000Z",
      currentPeriodEnd: "2027-04-16T02:00:00.000Z",
    });
    const invoices = await invoicesOf(tenant);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 900 * 2 * 12,
      periodStart: "2026-04-16T02:00:00.000Z",
      periodEnd: "2027-04-16T02:00:00.000Z",
    });
  });

  it("keeps the trial period and charges nothing when a plan is chosen during a trial", async () => {
    const tenant = await createTenant("prorate-trial-plan", "starter");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);

    const after = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    expect(after.currentPeriodStart).toBe(before?.currentPeriodStart);
    expect(after.currentPeriodEnd).toBe(before?.currentPeriodEnd);
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });
});

