    const invoices = await invoicesOf(tenant);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]).toMatchObject({
      amountCents: 900 * 2 * 12,
      periodStart: "2026-03-01T00:00:00.000Z",
      periodEnd: "2027-03-01T00:00:00.000Z",
    });
  });

  it("moves the free plan's periods on without invoicing", async () => {
    const tenant = await createTenant("renew-free", "free");
    await setSubscription(tenant, {
      currentPeriodStart: "2026-01-10T00:00:00.000Z",
      currentPeriodEnd: "2026-02-10T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));

    expect(await invoicesOf(tenant)).toHaveLength(0);
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.currentPeriodEnd).toBe(
      "2026-04-10T00:00:00.000Z",
    );
  });

  it("ends a cancellation on its date, moving the org to the free plan once", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    await setSubscription(tenant, {
      status: "canceled",
      currentPeriodStart: "2026-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-04-01T00:00:00.000Z",
      cancelAt: "2026-04-01T00:00:00.000Z",
    });
    const changes = capture("billing.plan_changed");

    await runBillingRenewalJob(new Date("2026-03-31T23:00:00.000Z"));
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("canceled");
    expect(changes).toHaveLength(0);

    const now = new Date("2026-04-02T00:00:00.000Z");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "free",
      status: "active",
      cancelAt: null,
      interval: "monthly",
      currentPeriodStart: "2026-04-01T00:00:00.000Z",
      currentPeriodEnd: "2026-05-01T00:00:00.000Z",
    });
    expect(changes).toEqual([
      expect.objectContaining({ orgId: tenant.org.id, actorId: null, from: "growth", to: "free" }),
    ]);
    expect(await invoicesOf(tenant)).toHaveLength(0);
  });

  it("leaves trials, past-due subscriptions and archived orgs alone", async () => {
    const trial = await createTenant("renew-trial", "growth");
    const pastDue = await createTenant("renew-past-due", "growth");
    const archived = await createTenant("renew-archived", "growth");
    const ended = {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    };
    await setSubscription(trial, ended);
    await setSubscription(pastDue, { ...ended, status: "past_due" });
    await setSubscription(archived, { ...ended, status: "active" });
    getDb()
      .update(organizations)
      .set({ archivedAt: "2026-02-15T00:00:00.000Z" })
      .where(eq(organizations.id, archived.org.id))
      .run();

    await runBillingRenewalJob(new Date("2026-03-15T00:00:00.000Z"));

    for (const tenant of [trial, pastDue, archived]) {
      expect((await subscriptionRepo.findSubscription(tenant.org.id))?.currentPeriodEnd).toBe(
        "2026-02-01T00:00:00.000Z",
      );
      expect(await invoicesOf(tenant)).toHaveLength(0);
    }
  });
});

