/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const now = new Date();
  const current = await subscriptionRepo.findSubscription(input.orgId);
  const currentPlan = current?.plan ?? (await planFor(input.orgId));

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  // Leaving the free plan for a paid one starts a fresh, fully charged
  // period now; every other change keeps the current period.
  const startsPaidPeriod =
    current !== null &&
    current.status !== "trialing" &&
    !isPaidPlan(current.plan) &&
    isPaidPlan(input.plan);

  const freshPeriod = startsPaidPeriod
    ? {
        start: toIsoTimestamp(now),
        end: toIsoTimestamp(nextPeriodEnd(now, input.interval)),
      }
    : undefined;

  const subscription = await subscriptionRepo.updateSubscriptionPlan(
    input.orgId,
    input.plan,
    input.interval,
    freshPeriod,
  );

  if (freshPeriod !== undefined) {
    await issueInvoice(
      input.orgId,
      {
        amountCents: periodChargeCents(
          input.plan,
          subscription.seats,
          input.interval,
        ),
        periodStart: freshPeriod.start,
        periodEnd: freshPeriod.end,
      },
      now,
      actor.userId,
    );
  } else if (
    current !== null &&
    current.status === "active" &&
    isPaidPlan(current.plan) &&
    isPaidPlan(input.plan)
  ) {
    // An upgrade is charged the price difference for the rest of the period;
    // a downgrade or an unchanged plan is charged nothing.
    const perSeatDifference = Math.max(
      0,
      getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(current.plan).priceCentsPerSeatMonthly,
    );

    await issueInvoice(
      input.orgId,
      {
        amountCents: prorateCents(
          perSeatDifference * current.seats * monthsIn(current.interval),
          current,
          now,
        ),
        periodStart: current.currentPeriodStart,
        periodEnd: current.currentPeriodEnd,
      },
      now,
      actor.userId,
    );
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const now = new Date();
  const current = await subscriptionRepo.findSubscription(input.orgId);
  const plan = current?.plan ?? (await planFor(input.orgId));

  if (input.seats > getLimit(plan, "seats")) {
    throw new Error(`Plan ${plan} tops out at ${getLimit(plan, "seats")} seats`);
  }

  const subscription = await subscriptionRepo.updateSeatCount(
    input.orgId,
    input.seats,
  );

  // Seats added to a paid, active subscription are charged for the rest of
  // the period; removing seats neither charges nor credits anything.
  const seatsAdded = current === null ? 0 : input.seats - current.seats;
  if (
    current !== null &&
    current.status === "active" &&
    isPaidPlan(current.plan) &&
    seatsAdded > 0
  ) {
    await issueInvoice(
      input.orgId,
      {
        amountCents: prorateCents(
          periodChargeCents(current.plan, seatsAdded, current.interval),
          current,
          now,
        ),
        periodStart: current.currentPeriodStart,
        periodEnd: current.currentPeriodEnd,
      },
      now,
      actor.userId,
    );
  }

  return subscription;
}

